// Diagonally Covered Hopf Fractal
// ShaderToy-compatible GLSL

#ifdef GL_ES
precision mediump float;
#endif

// A helper function for quaternion multiplication
vec4 qMul(in vec4 a, in vec4 b)
{
    // Quaternion components: (w, x, y, z)
    return vec4(
        a.x*b.x - a.y*b.y - a.z*b.z - a.w*b.w,  // w
        a.x*b.y + a.y*b.x + a.z*b.w - a.w*b.z,  // x
        a.x*b.z - a.y*b.w + a.z*b.x + a.w*b.y,  // y
        a.x*b.w + a.y*b.z - a.z*b.y + a.w*b.x   // z
    );
}

// Compute the argument of a 2D vector (re, im)
float argument(in vec2 c)
{
    return atan(c.y, c.x);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Normalized pixel coordinates (range: roughly -aspect..aspect in x, -1..1 in y)
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    // Inverse stereographic projection from (x, y, 0) in R^3 onto S^3
    float r2 = dot(uv, uv);
    // Our initial quaternion P in S^3
    // S^3 as (X, Y, Z, W)
    vec4 P = vec4(
        2.0 * uv.x,
        2.0 * uv.y,
        0.0,
        r2 - 1.0
    ) / (r2 + 1.0);

    // Time-based rotation angle in SO(3) is alpha = t/2
    // Then quaternion rotation angle is alpha/2 = t/4
    float alpha = iTime * 0.5;
    float halfAngle = alpha * 0.5;

    // Diagonal axis = (1,1,1)/sqrt(3)
    float invSqrt3 = 1.0 / sqrt(3.0);
    // Quaternion Q(t) in SU(2)
    vec4 Q = vec4(
        cos(halfAngle),
        sin(halfAngle) * invSqrt3,
        sin(halfAngle) * invSqrt3,
        sin(halfAngle) * invSqrt3
    );

    // Apply the group action: rotatedP = Q * P
    vec4 rotatedP = qMul(Q, P);

    // Interpret rotatedP as (a, b) in C^2:
    //   a = x0 + i*x1 = rotatedP.x + i*rotatedP.y
    //   b = x2 + i*x3 = rotatedP.z + i*rotatedP.w
    vec2 a = vec2(rotatedP.x, rotatedP.y);
    vec2 b = vec2(rotatedP.z, rotatedP.w);

    // Compute the base = b/a in C (if a ~= 0)
    // If |a| is extremely small, we can simply color black or skip
    float aLen = dot(a, a);
    if(aLen < 1e-12)
    {
        fragColor = vec4(0.0);
        return;
    }
    vec2 base; // b/a
    // (b_r + i b_i)/(a_r + i a_i) = (b * conj(a)) / |a|^2
    vec2 bConjA = vec2(b.x*a.x + b.y*a.y, b.y*a.x - b.x*a.y);  // b * conj(a)
    base = bConjA / aLen;

    // The fiber = Arg(b) - Arg(a)
    float fiber = argument(b) - argument(a);
    // Keep it in [-pi, pi], though not strictly necessary
    fiber = mod(fiber + 3.1415927, 6.2831853) - 3.1415927;

    // =========== Julia-like iteration on base =============
    // For interesting fractals, try different c values
    // e.g. c = (-0.4, 0.6), or (0.355, 0.355), etc.
    vec2 c = vec2(-0.4, 0.6);

    int maxIter = 40;
    int count = 0;
    vec2 z = base;
    for(int i = 0; i < maxIter; i++)
    {
        // z_{n+1} = z_n^2 + c
        // z^2 = (x + i y)^2 = (x^2 - y^2) + i (2xy)
        float x2 = z.x*z.x - z.y*z.y;
        float y2 = 2.0 * z.x*z.y;
        z = vec2(x2, y2) + c;

        if(dot(z, z) > 4.0)
        {
            break;
        }
        count++;
    }

    // Normalized iteration count
    float t = float(count) / float(maxIter);

    // Combine iteration count with a fiber-based modulation
    // Example: use a simple sin/cos of the fiber
    float modFiber = 0.5 + 0.5 * cos(fiber * 3.0);

    // Final color (pick your favorite palette)
    vec3 col = vec3(t * modFiber, t, t * (1.0 - modFiber));

    fragColor = vec4(col, 1.0);
}
